            flex-shrink: 0;
            box-shadow: none;
        }

        .comment-btn:hover {
            color: #05a850;
            transform: none;
            box-shadow: none;
        }

        .comment-btn:active {
            transform: none;
            box-shadow: none;
        }

        /* 确保头部布局不会变形 */
        .header {
            flex-wrap: wrap;
        }

        .header-left {
            flex-shrink: 1;
            overflow: hidden;
            min-width: 0;
        }

        .header-title {
            white-space: nowrap;
