function getFanqieEmojiMap(baseUrl) {
    var root = String(baseUrl || "").replace(/\/$/, "");
    var result = {};
    Object.keys(FANQIE_EMOJI_PATHS).forEach(function(name) {
        result[name] = root + FANQIE_EMOJI_PATHS[name];
    });
    return result;
